CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('admin','analyst');
CREATE TYPE incident_status AS ENUM ('open','investigating','resolved');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK (email = lower(email) AND length(email) <= 254), password_hash text NOT NULL, role user_role NOT NULL DEFAULT 'analyst', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE CHECK (length(trim(name)) BETWEEN 2 AND 100), owner_team text NOT NULL CHECK (length(trim(owner_team)) > 0));
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK (length(trim(title)) BETWEEN 5 AND 180), summary text NOT NULL CHECK (length(trim(summary)) >= 10), service_id uuid NOT NULL REFERENCES services(id) ON DELETE RESTRICT, severity smallint NOT NULL CHECK (severity BETWEEN 1 AND 5), status incident_status NOT NULL DEFAULT 'open', root_cause text, occurred_at timestamptz NOT NULL, resolved_at timestamptz, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (resolved_at IS NULL OR resolved_at >= occurred_at), CHECK (status <> 'resolved' OR (resolved_at IS NOT NULL AND nullif(trim(root_cause),'') IS NOT NULL)));
CREATE TABLE incident_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id), event_type text NOT NULL CHECK (event_type IN ('created','status_changed','root_cause_updated','deleted')), detail jsonb NOT NULL DEFAULT '{}', happened_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE symptoms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL UNIQUE CHECK (length(trim(label)) BETWEEN 3 AND 100));
CREATE TABLE incident_symptoms (incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE, symptom_id uuid NOT NULL REFERENCES symptoms(id) ON DELETE RESTRICT, PRIMARY KEY (incident_id,symptom_id));
CREATE INDEX incidents_service_time_idx ON incidents(service_id, occurred_at DESC);
CREATE INDEX incidents_status_severity_idx ON incidents(status, severity);
CREATE INDEX incidents_search_idx ON incidents USING gin(to_tsvector('english', title || ' ' || summary || ' ' || coalesce(root_cause,'')));
CREATE INDEX events_incident_time_idx ON incident_events(incident_id,happened_at DESC);
CREATE VIEW service_failure_summary AS SELECT s.id service_id,s.name service_name,count(i.id) incident_count,count(i.id) FILTER (WHERE i.status <> 'resolved') active_count,round(avg(i.severity)::numeric,2) avg_severity FROM services s LEFT JOIN incidents i ON i.service_id=s.id GROUP BY s.id,s.name;
CREATE FUNCTION touch_incident() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER incidents_touch BEFORE UPDATE ON incidents FOR EACH ROW EXECUTE FUNCTION touch_incident();
CREATE FUNCTION audit_incident() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO incident_events(incident_id,actor_id,event_type,detail) VALUES(NEW.id,NEW.created_by,'created',jsonb_build_object('status',NEW.status)); ELSIF OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO incident_events(incident_id,event_type,detail) VALUES(NEW.id,'status_changed',jsonb_build_object('from',OLD.status,'to',NEW.status)); END IF; IF TG_OP='UPDATE' AND OLD.root_cause IS DISTINCT FROM NEW.root_cause THEN INSERT INTO incident_events(incident_id,event_type,detail) VALUES(NEW.id,'root_cause_updated',jsonb_build_object('root_cause',NEW.root_cause)); END IF; RETURN NEW; END $$;
CREATE TRIGGER incidents_audit AFTER INSERT OR UPDATE ON incidents FOR EACH ROW EXECUTE FUNCTION audit_incident();
CREATE FUNCTION resolve_incident(p_id uuid,p_root_cause text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF nullif(trim(p_root_cause),'') IS NULL THEN RAISE EXCEPTION 'Root cause required'; END IF; UPDATE incidents SET status='resolved',root_cause=p_root_cause,resolved_at=now() WHERE id=p_id AND status<>'resolved'; IF NOT FOUND THEN RAISE EXCEPTION 'Incident missing or already resolved'; END IF; END $$;
